export interface MaskConfig {
  id: MaskType
  label: string
  emoji: string
}

export const AVAILABLE_MASKS: MaskConfig[] = [
  { id: 'none', label: 'None', emoji: '🚫' },
  // Polished emoji-based masks
  { id: 'kitty', label: 'Kitty', emoji: '😺' },
  { id: 'puppy', label: 'Puppy', emoji: '🐶' },
  { id: 'fox', label: 'Fox', emoji: '🦊' },
