  // Advanced contour-based masks
  { id: 'lipstick', label: 'Lipstick', emoji: '💄' },
  { id: 'cyber', label: 'Cyber', emoji: '🤖' },
  // Geometric primitives (legacy)
  { id: 'cat', label: 'Cat (geo)', emoji: '🐱' },
  { id: 'dog', label: 'Dog (geo)', emoji: '🐕' },
  { id: 'alien', label: 'Alien', emoji: '👽' },
  { id: 'robot', label: 'Robot', emoji: '🤖' },
  { id: 'clown', label: 'Clown', emoji: '🤡' },
  { id: 'skull', label: 'Skull', emoji: '💀' },
]

interface MaskStore {
  selectedMask: MaskType
  maskEnabled: boolean
  setMask: (mask: MaskType) => void
  toggleMask: (enabled: boolean) => void
  loadPreferences: () => Promise<void>
}

const STORAGE_KEY = '@mask_preferences'

export const useMaskStore = create<MaskStore>((set, get) => ({
  selectedMask: 'none',
  maskEnabled: false,

  setMask: (mask: MaskType) => {
    set({ selectedMask: mask, maskEnabled: mask !== 'none' })
    AsyncStorage.setItem(STORAGE_KEY, JSON.stringify({ selectedMask: mask, maskEnabled: mask !== 'none' }))
    if (mask === 'none') {
      removeNativeMask()
    } else {
      setNativeMask(mask)
    }
  },

  toggleMask: (enabled: boolean) => {
    set({ maskEnabled: enabled })
    const { selectedMask } = get()
    AsyncStorage.setItem(STORAGE_KEY, JSON.stringify({ selectedMask, maskEnabled: enabled }))
    if (!enabled) {
      removeNativeMask()
    } else {
      setNativeMask(selectedMask)
    }
  },

  loadPreferences: async () => {
    try {
      const stored = await AsyncStorage.getItem(STORAGE_KEY)
      if (stored) {
        const { selectedMask, maskEnabled } = JSON.parse(stored)
        set({ selectedMask, maskEnabled })
      }
    } catch (e) {
      console.warn('Failed to load mask preferences:', e)
    }
  },
}))

