package expo.modules.facemask;

import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Matrix;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.Rect;
import android.graphics.RectF;
import android.util.Log;

import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.Tasks;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.face.Face;
import com.google.mlkit.vision.face.FaceDetection;
import com.google.mlkit.vision.face.FaceDetector;
import com.google.mlkit.vision.face.FaceDetectorOptions;
import com.google.mlkit.vision.face.FaceLandmark;
import com.oney.WebRTCModule.videoEffects.VideoFrameProcessor;

import org.webrtc.JavaI420Buffer;
import org.webrtc.SurfaceTextureHelper;
import org.webrtc.TextureBufferImpl;
import org.webrtc.VideoFrame;
import org.webrtc.VideoFrameDrawer;
import org.webrtc.YuvConverter;

import java.nio.ByteBuffer;
import java.util.List;
import java.util.concurrent.ExecutionException;

public class FaceMaskProcessor implements VideoFrameProcessor {
    private static final String TAG = "FaceMaskProcessor";
    private String maskType = "none";
    private final FaceDetector detector;
    private final VideoFrameDrawer frameDrawer = new VideoFrameDrawer();
    private final YuvConverter yuvConverter = new YuvConverter();
    private Bitmap bitmapBuffer;
    private Canvas canvas;
    private List<Face> lastFaces;
    private int frameCount = 0;
    private boolean processing = false;

    public FaceMaskProcessor() {
        FaceDetectorOptions options = new FaceDetectorOptions.Builder()
                .setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_FAST)
                .setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_ALL)
                .setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_NONE)
                .build();
        detector = FaceDetection.getClient(options);
    }

    public void setMaskType(String maskType) {
        this.maskType = maskType;
    }

    @Override
    public VideoFrame process(VideoFrame frame, SurfaceTextureHelper textureHelper) {
        if ("none".equals(maskType)) {
            return frame;
        }

        frameCount++;
        boolean shouldDetect = (frameCount % 3 == 0) && !processing;

        VideoFrame.Buffer buffer = frame.getBuffer();
        int width = buffer.getWidth();
        int height = buffer.getHeight();

        // Initialize bitmap buffer if needed
        if (bitmapBuffer == null || bitmapBuffer.getWidth() != width || bitmapBuffer.getHeight() != height) {
            bitmapBuffer = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888);
            canvas = new Canvas(bitmapBuffer);
        }

        // Draw VideoFrame to Bitmap
        VideoFrame.I420Buffer i420Buffer = buffer.toI420();
        drawI420ToBitmap(i420Buffer, bitmapBuffer);
        i420Buffer.release();

        if (shouldDetect) {
            processing = true;
            detectFaces(bitmapBuffer);
            processing = false;
        }

        if (lastFaces == null || lastFaces.isEmpty()) {
            return frame;
        }

        // Draw masks on the bitmap
        for (Face face : lastFaces) {
            drawMask(canvas, face, width, height);
        }

        // Convert Bitmap back to VideoFrame
        // This is a simplified version - in a production app you'd use a more efficient way
        // like uploading the bitmap back to a texture or using a direct buffer.
        VideoFrame.Buffer outputBuffer = bitmapToI420Buffer(bitmapBuffer);
        return new VideoFrame(outputBuffer, frame.getRotation(), frame.getTimestampNs());
    }

    private void detectFaces(Bitmap bitmap) {
        InputImage image = InputImage.fromBitmap(bitmap, 0);
        Task<List<Face>> result = detector.process(image);
        try {
            lastFaces = Tasks.await(result);
        } catch (ExecutionException | InterruptedException e) {
            Log.e(TAG, "Face detection failed", e);
        }
    }

    private void drawI420ToBitmap(VideoFrame.I420Buffer i420Buffer, Bitmap bitmap) {
        // Simple I420 to ARGB conversion for the bitmap
        int width = i420Buffer.getWidth();
        int height = i420Buffer.getHeight();
        int[] argb = new int[width * height];

        ByteBuffer yBuf = i420Buffer.getDataY();
        ByteBuffer uBuf = i420Buffer.getDataU();
        ByteBuffer vBuf = i420Buffer.getDataV();

        int yStride = i420Buffer.getStrideY();
        int uStride = i420Buffer.getStrideU();
        int vStride = i420Buffer.getStrideV();

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int yIdx = y * yStride + x;
                int uvIdx = (y / 2) * uStride + (x / 2);

                int Y = yBuf.get(yIdx) & 0xFF;
                int U = (uBuf.get(uvIdx) & 0xFF) - 128;
                int V = (vBuf.get(uvIdx) & 0xFF) - 128;

                int R = (int) (Y + 1.402 * V);
                int G = (int) (Y - 0.344136 * U - 0.714136 * V);
                int B = (int) (Y + 1.772 * U);

                R = Math.max(0, Math.min(255, R));
                G = Math.max(0, Math.min(255, G));
                B = Math.max(0, Math.min(255, B));

                argb[y * width + x] = 0xFF000000 | (R << 16) | (G << 8) | B;
            }
        }
        bitmap.setPixels(argb, 0, width, 0, 0, width, height);
    }

    private VideoFrame.Buffer bitmapToI420Buffer(Bitmap bitmap) {
        int width = bitmap.getWidth();
        int height = bitmap.getHeight();
        int[] argb = new int[width * height];
        bitmap.getPixels(argb, 0, width, 0, 0, width, height);

        byte[] yuv = new byte[width * height * 3 / 2];
        encodeYUV420SP(yuv, argb, width, height);

        ByteBuffer yBuffer = ByteBuffer.allocateDirect(width * height);
        ByteBuffer uBuffer = ByteBuffer.allocateDirect(width * height / 4);
        ByteBuffer vBuffer = ByteBuffer.allocateDirect(width * height / 4);

        yBuffer.put(yuv, 0, width * height);
        uBuffer.put(yuv, width * height, width * height / 4);
        vBuffer.put(yuv, width * height + width * height / 4, width * height / 4);

        yBuffer.position(0);
        uBuffer.position(0);
        vBuffer.position(0);

        return JavaI420Buffer.wrap(width, height, yBuffer, width, uBuffer, width / 2, vBuffer, width / 2, null);
    }

    private void encodeYUV420SP(byte[] yuv420sp, int[] argb, int width, int height) {
        final int frameSize = width * height;
        int yIndex = 0;
        int uvIndex = frameSize;

        for (int j = 0; j < height; j++) {
            for (int i = 0; i < width; i++) {
                int R = (argb[yIndex] & 0xff0000) >> 16;
                int G = (argb[yIndex] & 0xff00) >> 8;
                int B = (argb[yIndex] & 0xff);

                int Y = ((66 * R + 129 * G + 25 * B + 128) >> 8) + 16;
                int U = ((-38 * R - 74 * G + 112 * B + 128) >> 8) + 128;
                int V = ((112 * R - 94 * G - 18 * B + 128) >> 8) + 128;

                yuv420sp[yIndex++] = (byte) Math.max(0, Math.min(255, Y));
                if (j % 2 == 0 && i % 2 == 0) {
                    yuv420sp[uvIndex++] = (byte) Math.max(0, Math.min(255, U));
                    yuv420sp[uvIndex++] = (byte) Math.max(0, Math.min(255, V));
                }
            }
        }
    }

    private void drawMask(Canvas canvas, Face face, int width, int height) {
        Rect bounds = face.getBoundingBox();
        float cx = bounds.centerX();
        float cy = bounds.centerY();
        float fw = bounds.width();
        float fh = bounds.height();

        Paint paint = new Paint();
        paint.setAntiAlias(true);

        switch (maskType) {
            case "cat":
                drawCat(canvas, cx, cy, fw, fh, face, paint);
                break;
            case "dog":
                drawDog(canvas, cx, cy, fw, fh, face, paint);
                break;
            case "alien":
                drawAlien(canvas, cx, cy, fw, fh, face, paint);
                break;
            case "robot":
                drawRobot(canvas, cx, cy, fw, fh, face, paint);
                break;
            case "clown":
                drawClown(canvas, cx, cy, fw, fh, face, paint);
                break;
            case "skull":
                drawSkull(canvas, cx, cy, fw, fh, face, paint);
                break;
        }
    }

    // Mask drawing helpers (simplified version of the iOS ones)
    private void drawCat(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Ears
        paint.setColor(Color.argb(210, 64, 64, 64));
        Path path = new Path();
        path.moveTo(cx - fw * 0.3f, cy - fh * 0.4f);
        path.lineTo(cx - fw * 0.45f, cy - fh * 0.7f);
        path.lineTo(cx - fw * 0.1f, cy - fh * 0.45f);
        path.close();
        canvas.drawPath(path, paint);

        path.reset();
        path.moveTo(cx + fw * 0.3f, cy - fh * 0.4f);
        path.lineTo(cx + fw * 0.45f, cy - fh * 0.7f);
        path.lineTo(cx + fw * 0.1f, cy - fh * 0.45f);
        path.close();
        canvas.drawPath(path, paint);

        // Nose
        paint.setColor(Color.argb(230, 255, 120, 150));
        canvas.drawCircle(cx, cy + fh * 0.05f, fw * 0.08f, paint);
    }

    private void drawDog(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Floppy ears
        paint.setColor(Color.argb(210, 140, 90, 40));
        canvas.drawOval(new RectF(cx - fw * 0.6f, cy - fh * 0.2f, cx - fw * 0.3f, cy + fh * 0.4f), paint);
        canvas.drawOval(new RectF(cx + fw * 0.3f, cy - fh * 0.2f, cx + fw * 0.6f, cy + fh * 0.4f), paint);

        // Big nose
        paint.setColor(Color.argb(230, 30, 30, 30));
        canvas.drawCircle(cx, cy + fh * 0.1f, fw * 0.12f, paint);
    }

    private void drawAlien(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Big black eyes
        paint.setColor(Color.argb(220, 0, 0, 0));
        canvas.drawOval(new RectF(cx - fw * 0.4f, cy - fh * 0.1f, cx - fw * 0.1f, cy + fh * 0.1f), paint);
        canvas.drawOval(new RectF(cx + fw * 0.1f, cy - fh * 0.1f, cx + fw * 0.4f, cy + fh * 0.1f), paint);

        // Green pupils
        paint.setColor(Color.argb(230, 100, 255, 100));
        canvas.drawCircle(cx - fw * 0.25f, cy, fw * 0.03f, paint);
        canvas.drawCircle(cx + fw * 0.25f, cy, fw * 0.03f, paint);
    }

    private void drawRobot(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Square eyes
        paint.setColor(Color.argb(220, 0, 200, 255));
        canvas.drawRect(cx - fw * 0.35f, cy - fh * 0.1f, cx - fw * 0.15f, cy + fh * 0.1f, paint);
        canvas.drawRect(cx + fw * 0.15f, cy - fh * 0.1f, cx + fw * 0.35f, cy + fh * 0.1f, paint);

        // Antenna
        paint.setColor(Color.GRAY);
        canvas.drawRect(cx - 5, cy - fh * 0.7f, cx + 5, cy - fh * 0.4f, paint);
        paint.setColor(Color.RED);
        canvas.drawCircle(cx, cy - fh * 0.7f, 10, paint);
    }

    private void drawClown(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Red nose
        paint.setColor(Color.RED);
        canvas.drawCircle(cx, cy, fw * 0.15f, paint);

        // Smile
        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(10);
        canvas.drawArc(new RectF(cx - fw * 0.3f, cy + fh * 0.1f, cx + fw * 0.3f, cy + fh * 0.3f), 0, 180, false, paint);
    }

    private void drawSkull(Canvas canvas, float cx, float cy, float fw, float fh, Face face, Paint paint) {
        // Hollow eyes
        paint.setColor(Color.BLACK);
        canvas.drawCircle(cx - fw * 0.2f, cy - fh * 0.1f, fw * 0.12f, paint);
        canvas.drawCircle(cx + fw * 0.2f, cy - fh * 0.1f, fw * 0.12f, paint);

        // Teeth
        paint.setColor(Color.WHITE);
        paint.setStrokeWidth(5);
        float mouthY = cy + fh * 0.25f;
        canvas.drawLine(cx - fw * 0.2f, mouthY, cx + fw * 0.2f, mouthY, paint);
        for (int i = 0; i < 5; i++) {
            float tx = cx - fw * 0.2f + (fw * 0.4f * i / 4f);
            canvas.drawLine(tx, mouthY - 10, tx, mouthY + 10, paint);
        }
    }
}

