        targetId,
        callId,
        offerType: offer.type,
      })

      const ws = get().ws
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'offer', to: targetId, callId, offer }))
        logCallStore('CALL_USER_OFFER_SENT', { targetId, callId })
      } else {
        logCallWarn('CALL_USER_OFFER_NOT_SENT_WS_UNAVAILABLE', callSnapshot())
      }
