// Clown mask: red nose + rainbow hair + smile
function ClownMask({ centerX, centerY, w, h }: { centerX: number; centerY: number; w: number; h: number }) {
  const noseY = centerY + h * 0.02

  // Rainbow hair arcs
  const hairY = centerY - h * 0.35
  const hairPath = Skia.Path.Make()
  hairPath.addArc({ x: centerX - w * 0.45, y: hairY - h * 0.1, width: w * 0.9, height: h * 0.3 }, 180, 180)

  return (
    <Group>
      {/* Hair */}
      <Path path={hairPath} color="rgba(255, 100, 0, 0.7)" style="stroke" strokeWidth={8} />
      {/* Big red nose */}
      <Circle cx={centerX} cy={noseY} r={w * 0.1} color="rgba(255, 0, 0, 0.9)" />
      {/* Smile */}
      <Path
        path={makeSmile(centerX, centerY + h * 0.15, w * 0.3, h * 0.08)}
        color="rgba(255, 0, 0, 0.8)"
        style="stroke"
        strokeWidth={3}
      />
    </Group>
  )
}

// Skull mask: hollow eyes + nose hole + teeth
function SkullMask({ centerX, centerY, w, h }: { centerX: number; centerY: number; w: number; h: number }) {
  const eyeY = centerY - h * 0.08
  const eyeR = w * 0.1

  const noseY = centerY + h * 0.05
  const nose = Skia.Path.Make()
  nose.moveTo(centerX, noseY - h * 0.04)
  nose.lineTo(centerX - w * 0.04, noseY + h * 0.03)
  nose.lineTo(centerX + w * 0.04, noseY + h * 0.03)
  nose.close()

  const mouthY = centerY + h * 0.18

  return (
    <Group>
      {/* Eye sockets */}
      <Circle cx={centerX - w * 0.17} cy={eyeY} r={eyeR} color="rgba(0, 0, 0, 0.85)" />
      <Circle cx={centerX + w * 0.17} cy={eyeY} r={eyeR} color="rgba(0, 0, 0, 0.85)" />
      {/* Nose */}
      <Path path={nose} color="rgba(0, 0, 0, 0.8)" />
      {/* Teeth */}
      {[-0.15, -0.05, 0.05, 0.15].map((offset, i) => (
        <Path
          key={i}
          path={makeWhisker(
            centerX + w * offset, mouthY - h * 0.02,
            centerX + w * offset, mouthY + h * 0.05
          )}
          color="rgba(255, 255, 255, 0.9)"
          style="stroke"
          strokeWidth={2.5}
        />
      ))}
      {/* Jaw line */}
      <Path
        path={makeWhisker(centerX - w * 0.2, mouthY, centerX + w * 0.2, mouthY)}
        color="rgba(255, 255, 255, 0.7)"
        style="stroke"
        strokeWidth={1.5}
      />
    </Group>
  )
}

// Helper: create a line path between two points
function makeWhisker(x1: number, y1: number, x2: number, y2: number) {
  const path = Skia.Path.Make()
  path.moveTo(x1, y1)
  path.lineTo(x2, y2)
  return path
}

// Helper: create a smile arc
function makeSmile(cx: number, cy: number, w: number, h: number) {
  const path = Skia.Path.Make()
  path.addArc({ x: cx - w, y: cy - h, width: w * 2, height: h * 2 }, 0, 180)
  return path
}

