import React, { useState, useEffect } from 'react'
import { Alert, TouchableOpacity, Image, ScrollView } from 'react-native'
import { View, Text, StyleSheet, Share, Linking, Platform, AppState } from 'react-native'
import { useAuthStore } from '@/store'
import { usePermissions } from '@/hooks/usePermissions'
import { fontFamily } from '@/utils/typography'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import AvailabilityStatus from '@/components/availability-status'
import AvailabilityButton from '@/components/availability-button'
import MaskSelector from '@/components/face-mask/MaskSelector'
import MaskPreview from '@/components/face-mask/MaskPreview'
import { useMaskStore } from '@/store/masks'
import { useRouter, useSegments, useNavigation } from 'expo-router'
import * as NavigationBar from 'expo-navigation-bar'
import * as ImagePicker from 'expo-image-picker'
import { Ionicons } from '@expo/vector-icons'
import { getInitials } from '@/utils'

const SettingsScreen = () => {
  const { user, logout, deleteAccount, editUser } = useAuthStore()
  const { loadPreferences } = useMaskStore()
  const [isUploading, setIsUploading] = useState(false)
  const isAvailable = user?.is_available || false
  const [notificationsEnabled, setNotificationsEnabled] = useState(false)
  const { requestNotificationPermission, checkNotificationPermission, openAppSettings } =
    usePermissions()
  const navigation = useNavigation()

  useEffect(() => {
    loadPreferences()
  }, [])

  const handlePickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.5,
    })

    if (!result.canceled) {
      uploadAvatar(result.assets[0].uri)
    }
  }

  const uploadAvatar = async (uri: string) => {
    setIsUploading(true)
    try {
      const formData = new FormData()
      const fileName = uri.split('/').pop()
      const match = /\.(\w+)$/.exec(fileName || '')
      const type = match ? `image/${match[1]}` : `image`

      formData.append('file', { uri, name: fileName, type } as any)

      // Assuming there's an endpoint for file upload
      const response = await fetch(`${process.env.EXPO_PUBLIC_BACKEND_URL}/api/upload_avatar`, {
        method: 'POST',
        body: formData,
        headers: {
          Authorization: `Bearer ${useAuthStore.getState().token}`,
          'Content-Type': 'multipart/form-data',
        },
      })

      const data = await response.json()
      if (data.url) {
        await editUser({ avatar_url: data.url })
        Alert.alert('Success', 'Avatar updated successfully')
      }
    } catch (error) {
      console.error('Upload failed:', error)
      Alert.alert('Error', 'Failed to upload avatar')
    } finally {
      setIsUploading(false)
    }
  }

  const onDelete = () => {
    Alert.alert('Confirm account delete', 'Are you sure?', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Delete', style: 'destructive', onPress: () => deleteAccount() },
    ])
  }

  const onLogout = () => {
    Alert.alert('Confirm Logout', 'Are you sure you want to log out?', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Logout', style: 'destructive', onPress: () => logout() },
    ])
  }

  // Listen for app state changes to refresh screen when app comes to foreground
  useEffect(() => {
    const checkPermissions = async () => {
      const hasPermission = await checkNotificationPermission()
      setNotificationsEnabled(hasPermission)
    }

    // Initial check
    checkPermissions()

    // Set up AppState listener for foreground/background transitions
    const subscription = AppState.addEventListener('change', nextAppState => {
      if (nextAppState === 'active') {
        // App has come to the foreground
        checkPermissions()
      }
    })

    // Clean up
    return () => {
      subscription.remove()
    }
  }, [])

  // With Expo Router, we can use the navigation focus listener
  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', () => {
      // This will run when the screen comes into focus
      const checkPermissions = async () => {
        const hasPermission = await checkNotificationPermission()
        setNotificationsEnabled(hasPermission)
      }

      checkPermissions()
    })

    return unsubscribe
  }, [navigation])

  const handleInviteFriend = async () => {
    try {
      const phone = user?.phone
      if (!phone) return
      const webUrl = (process.env.EXPO_PUBLIC_WEB_URL || 'https://buzzbuzzme.vercel.app').replace(/\/$/, '')
      const link = `${webUrl}/contact?phone=${encodeURIComponent(phone)}`
      await Share.share({
        message: `Add me on BuzzBuzzMe! ${link}`,
        url: link,
        title: 'Invite a friend to join!',
      })
    } catch (error) {}
  }

  const handleNotificationToggle = async () => {
    const hasPermission = await checkNotificationPermission()

    if (hasPermission) {
      // If already enabled, direct to settings to disable
      openAppSettings()
    } else {
      // Request permission
      const granted = await requestNotificationPermission()
      setNotificationsEnabled(granted)
      if (!granted) {
        // If not granted, direct user to settings
        openAppSettings()
      }
    }
  }

  const handleGiveFeedback = () => {
    Linking.openURL('mailto:feedback@yourdomain.com?subject=App Feedback')
  }

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.contentContainer}>
      {/* Top Section - Availability */}
      <View style={styles.topSection}>
        <View
          style={{
            flexDirection: 'row',
            justifyContent: 'space-between',
            alignItems: 'center',
            width: '100%',
          }}
        >
          <AvailabilityStatus />
          <TouchableOpacity onPress={handlePickImage} disabled={isUploading}>
            <View style={styles.avatarContainer}>
              {user?.avatar_url ? (
                <Image source={{ uri: user.avatar_url }} style={styles.avatar} />
              ) : (
                <View style={styles.avatarPlaceholder}>
                  <Text style={styles.avatarText}>{getInitials(user?.phone || 'U')}</Text>
                </View>
              )}
              <View style={styles.editBadge}>
                <Ionicons name="camera" size={12} color="white" />
              </View>
            </View>
          </TouchableOpacity>
        </View>
        <AvailabilityButton />
        <Card
          style={{
            width: '100%',
            height: 56,
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(102, 102, 102, 0.44)',
          }}
        >
          <Text
            style={{
              color: 'white',
              fontFamily: fontFamily.semibold,
              fontSize: 18,
              lineHeight: 22,
            }}
          >
            {user.phone}
          </Text>
        </Card>

        <View style={styles.actions}>
          <Button variant="subtle" onPress={handleInviteFriend}>
            invite friend
          </Button>

          <Button variant="subtle" onPress={handleNotificationToggle}>
            {notificationsEnabled ? 'disable notifications' : 'enable notifications'}
          </Button>

