const PREVIEW_WIDTH = 200
const PREVIEW_HEIGHT = 260

/**
 * Live mask preview using VisionCamera + face detection.
 * Used in the settings screen to show how the mask looks on your face.
 */
export default function MaskPreview() {
  const { selectedMask, maskEnabled } = useMaskStore()
  const { hasPermission, requestPermission } = useCameraPermission()
  const device = useCameraDevice('front')
  const [faces, setFaces] = useState<Face[]>([])

  const { detectFaces } = useFaceDetector({
    performanceMode: 'fast',
    landmarkMode: 'all',
    contourMode: 'none',
    classificationMode: 'none',
  })

  const handleFacesDetected = Worklets.createRunOnJS((detectedFaces: Face[]) => {
    setFaces(detectedFaces)
  })

  const frameProcessor = useFrameProcessor(frame => {
    'worklet'
    const detected = detectFaces(frame)
    handleFacesDetected(detected)
  }, [detectFaces, handleFacesDetected])

  if (!maskEnabled || selectedMask === 'none') {
    return null
  }

  if (!hasPermission) {
    return (
      <View style={styles.container}>
        <Text style={styles.permissionText} onPress={requestPermission}>
          tap to enable camera for mask preview
        </Text>
      </View>
    )
  }

  if (!device) {
    return (
      <View style={styles.container}>
        <Text style={styles.permissionText}>no front camera available</Text>
      </View>
    )
  }

  const face = faces[0]

  return (
    <View style={styles.container}>
      <View style={styles.preview}>
        <Camera
          style={StyleSheet.absoluteFill}
          device={device}
          isActive={true}
          frameProcessor={frameProcessor}
          pixelFormat="yuv"
        />
        {face && (
          <Canvas style={StyleSheet.absoluteFill}>
            <MaskOnFace type={selectedMask} face={face} previewWidth={PREVIEW_WIDTH} previewHeight={PREVIEW_HEIGHT} />
          </Canvas>
        )}
      </View>
    </View>
  )
}

