   184	    private void drawI420ToBitmap(VideoFrame.I420Buffer i420Buffer, Bitmap bitmap) {
   185	        // Simple I420 to ARGB conversion for the bitmap
   186	        int width = i420Buffer.getWidth();
   187	        int height = i420Buffer.getHeight();
   188	        int[] argb = new int[width * height];
   189	
   190	        ByteBuffer yBuf = i420Buffer.getDataY();
   191	        ByteBuffer uBuf = i420Buffer.getDataU();
   192	        ByteBuffer vBuf = i420Buffer.getDataV();
   193	
   194	        int yStride = i420Buffer.getStrideY();
   195	        int uStride = i420Buffer.getStrideU();
   196	        int vStride = i420Buffer.getStrideV();
   197	
   198	        for (int y = 0; y < height; y++) {
   199	            for (int x = 0; x < width; x++) {
   200	                int yIdx = y * yStride + x;
   201	                int uvIdx = (y / 2) * uStride + (x / 2);
   202	
   203	                int Y = yBuf.get(yIdx) & 0xFF;
   204	                int U = (uBuf.get(uvIdx) & 0xFF) - 128;
   205	                int V = (vBuf.get(uvIdx) & 0xFF) - 128;
   206	
   207	                int R = (int) (Y + 1.402 * V);
   208	                int G = (int) (Y - 0.344136 * U - 0.714136 * V);
   209	                int B = (int) (Y + 1.772 * U);
   210	
   211	                R = Math.max(0, Math.min(255, R));
   212	                G = Math.max(0, Math.min(255, G));
   213	                B = Math.max(0, Math.min(255, B));
   214	
   215	                argb[y * width + x] = 0xFF000000 | (R << 16) | (G << 8) | B;
   216	            }
   217	        }
   218	        bitmap.setPixels(argb, 0, width, 0, 0, width, height);
   219	    }
