   221	    private VideoFrame.Buffer bitmapToI420Buffer(Bitmap bitmap) {
   222	        int width = bitmap.getWidth();
   223	        int height = bitmap.getHeight();
   224	        int[] argb = new int[width * height];
   225	        bitmap.getPixels(argb, 0, width, 0, 0, width, height);
   226	
   227	        byte[] yuv = new byte[width * height * 3 / 2];
   228	        encodeYUV420SP(yuv, argb, width, height);
   229	
   230	        ByteBuffer yBuffer = ByteBuffer.allocateDirect(width * height);
   231	        ByteBuffer uBuffer = ByteBuffer.allocateDirect(width * height / 4);
   232	        ByteBuffer vBuffer = ByteBuffer.allocateDirect(width * height / 4);
   233	
   234	        yBuffer.put(yuv, 0, width * height);
   235	        uBuffer.put(yuv, width * height, width * height / 4);
   236	        vBuffer.put(yuv, width * height + width * height / 4, width * height / 4);
   237	
   238	        yBuffer.position(0);
   239	        uBuffer.position(0);
   240	        vBuffer.position(0);
   241	
   242	        return JavaI420Buffer.wrap(width, height, yBuffer, width, uBuffer, width / 2, vBuffer, width / 2, null);
   243	    }
