   252	                int R = (argb[yIndex] & 0xff0000) >> 16;
   253	                int G = (argb[yIndex] & 0xff00) >> 8;
   254	                int B = (argb[yIndex] & 0xff);
   255	
   256	                int Y = ((66 * R + 129 * G + 25 * B + 128) >> 8) + 16;
   257	                int U = ((-38 * R - 74 * G + 112 * B + 128) >> 8) + 128;
   258	                int V = ((112 * R - 94 * G - 18 * B + 128) >> 8) + 128;
