   260	                yuv420sp[yIndex++] = (byte) Math.max(0, Math.min(255, Y));
   261	                if (j % 2 == 0 && i % 2 == 0) {
   262	                    yuv420sp[uvIndex++] = (byte) Math.max(0, Math.min(255, U));
   263	                    yuv420sp[uvIndex++] = (byte) Math.max(0, Math.min(255, V));
   264	                }
   265	            }
   266	        }
   267	    }
